fn run_startup_inference_incremental(
    tx: std::sync::mpsc::Sender<crate::tui::splash::InferenceUpdate>,
) {
    use crate::tui::splash::InferenceUpdate;
    use std::io::Write as _;

    // ── start.log helper ──────────────────────────────────────────────────
    let log_path = "/tmp/strix-start.log";
    let t0 = std::time::Instant::now();
    // Truncate/create on entry so each run starts fresh.
    let mut log_file = std::fs::OpenOptions::new()
        .create(true).write(true).truncate(true)
        .open(log_path)
        .ok();
    let mut slog = move |msg: &str| {
        let ms = t0.elapsed().as_millis();
        let line = format!("[{:>7}ms] {}\n", ms, msg);
        if let Some(f) = log_file.as_mut() {
            let _ = f.write_all(line.as_bytes());
            let _ = f.flush();
        }
    };
    slog("=== strix startup inference BEGIN ===");

    let main_model  = read_strix_conf_model();
    let sub_model   = read_strix_conf_subagent_model();
    let max_history = read_strix_conf_quote_history_max();
    let mut cache   = load_quote_cache();
    let base_prompt = read_startup_prompt();
    let adjectives  = read_quote_adjectives();

    slog(&format!("main_model={main_model}  sub_model={sub_model}"));

    // 240s covers the 35B model's cold-start from disk on first inference.
    // Once the model is warm, the quote itself takes ~13–80 s depending on prompt.
    let client = match reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_secs(240))
        .build()
    {
        Ok(c) => c,
        Err(e) => {
            slog(&format!("ERROR building client: {e}"));
            let _ = tx.send(InferenceUpdate::Failed(e.to_string())); return;
        }
    };

    // Step 1 — Sub model generates the quote; up to 3 attempts.
    // Each attempt uses a different adjective combo so the model gets a fresh
    // angle if it refuses the previous one (e.g. "provokant" → "ironisch oder vergessen").
    const QUOTE_RETRIES: u32 = 3;
    slog("PHASE 1: quote generation START");
    let (quote, attribution) = {
        let mut last_err = String::new();
        let mut result: Option<(String, String)> = None;
        for attempt in 0..QUOTE_RETRIES {
            let adjektive = pick_quote_adjectives(&adjectives, attempt);
            let quote_prompt = build_quote_prompt(&base_prompt, &adjektive, &cache);
            slog(&format!("  quote attempt {attempt} START  adj={adjektive:?}"));
            // Tell the splash to start the live timer for this attempt.
            let _ = tx.send(InferenceUpdate::AttemptStarted {
                phase_label: format!("{sub_model} sucht ein Zitat"),
                attempt: attempt + 1,
            });
            let t_att = std::time::Instant::now();
            match chat_completion(&client, &sub_model, &quote_prompt) {
                Ok(r) => {
                    let dur = t_att.elapsed().as_millis();
                    // JSON format first (new prompt), plain text fallback (old/cache format)
                    let (q, a) = extract_quote_json(&r)
                        .unwrap_or_else(|| parse_quote_attribution(&r));
                    let q_trim = q.trim();
                    if q_trim.is_empty() {
                        last_err = "Modell gab nur Thinking-Block aus".to_string();
                        slog(&format!("  quote attempt {attempt} EMPTY ({dur}ms): {last_err}"));
                    } else if is_refusal_quote(q_trim) {
                        // Plain-text fallback path bypassed extract_quote_json's guard;
                        // catch refusals here so we retry with the next adjective.
                        last_err = format!(
                            "Modell-Verweigerung ({} Zeichen) — retry mit neuem Adjektiv",
                            q_trim.chars().count()
                        );

