fn chat_completion_full(client: &reqwest::blocking::Client, model: &str, prompt: &str, max_tokens: u32, max_reasoning: bool) -> Result<String, String> {
    // reasoning_effort MUSS gesetzt werden — der `/no_think`-Prefix im Prompt
    // wird vom Ollama-/v1/chat/completions-Endpoint ignoriert; nur das JSON-
    // Feld wird vom Backend (owl_daemon b3d1452) auf Ollamas natives /api/chat
    // mit `think:false|true` übersetzt.
    let body = serde_json::json!({
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": max_tokens,
        "stream": false,
        "reasoning_effort": if max_reasoning { "max" } else { "none" },
    });
    let resp = client
        .post("http://127.0.0.1:8081/v1/chat/completions")
        .json(&body)
        .send()
        .map_err(|e| format!("Verbindungsfehler: {e}"))?;
    if !resp.status().is_success() {
        return Err(format!("HTTP {}", resp.status()));
    }
    let json: serde_json::Value = resp.json().map_err(|e| format!("JSON-Fehler: {e}"))?;
    json.get("choices")
        .and_then(|c| c.get(0))
        .and_then(|c| c.get("message"))
        .and_then(|m| m.get("content"))
        .and_then(|s| s.as_str())
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| "Leere Modellantwort".to_string())
}

