pub fn cycle_preset(&mut self) -> Option<(String, String, String)> {
        if self.presets.is_empty() {
            return None;
        }
        self.current_preset_idx = (self.current_preset_idx + 1) % self.presets.len();
        let p = &self.presets[self.current_preset_idx];
        Some((p.name.clone(), p.model.clone(), p.subagent.clone()))
    }

    /// Dismiss the splash screen early (on keypress).
    pub fn dismiss_splash(&mut self) {
        if let Some(splash) = self.splash.as_mut() {
            let was_pending = matches!(splash.inference, crate::tui::splash::InferenceState::Pending);
            splash.dismiss();
            // User skipped while comment was still pending → close the rx immediately
            // so the background comment cannot sneak into startup_quote after TUI opens.
            if !was_pending && splash.is_dismissed() {
                self.startup_inference_rx = None;
            }
        }
    }

    /// Cycle reasoning-effort through the three behaviorally distinct tiers:
    /// `Off` → `High` → `Max` → `Off`.
    pub fn cycle_effort(&mut self) {
        self.reasoning_effort = self.reasoning_effort.cycle_next();
        self.last_effective_reasoning_effort = None;
        self.needs_redraw = true;
        self.push_status_toast(
            format!("Thinking: {}", self.reasoning_effort.short_label()),
            StatusToastLevel::Info,
            Some(1_500),
        );
    }

    /// Execute hooks for a specific event with the given context
    pub fn execute_hooks(&self, event: HookEvent, context: &HookContext) -> Vec<HookResult> {
        self.hooks.execute(event, context)
    }

